import{_ as e,a as o,b as a}from"./chunks/30.DJULZAiv.js";import{_ as s,o as r,c as i,a0 as l}from"./chunks/framework.DRjqbEpm.js";const g=JSON.parse('{"title":"📦 Backup & Restore","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/backup.md","filePath":"en/guide/backup.md"}'),n={name:"en/guide/backup.md"};function u(c,t,p,d,h,k){return r(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="📦-backup-restore" tabindex="-1">📦 Backup &amp; Restore <a class="header-anchor" href="#📦-backup-restore" aria-label="Permalink to &quot;📦 Backup &amp; Restore&quot;">​</a></h1><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>V-Train does not use any servers. All your data lives <strong>only on your computer</strong>. We do not have copies of your data. This keeps your data private. But it also means <strong>you must backup your data!</strong> Please backup often.</p></div><hr><h2 id="🔒-why-backup" tabindex="-1">🔒 Why Backup? <a class="header-anchor" href="#🔒-why-backup" aria-label="Permalink to &quot;🔒 Why Backup?&quot;">​</a></h2><p>V-Train saves all your data inside your web browser. This includes:</p><table tabindex="0"><thead><tr><th>Data Type</th><th>Description</th></tr></thead><tbody><tr><td>📊 Viewing History</td><td>How much of a video you have watched</td></tr><tr><td>⚙️ Settings</td><td>Colors, language, and switches</td></tr><tr><td>🗺️ Training Rules</td><td>The rules you made for new websites</td></tr><tr><td>❤️ Bookmarks</td><td>Your saved videos and folders</td></tr><tr><td>⭐ Ratings</td><td>The videos you liked or disliked</td></tr><tr><td>🖼️ Custom Covers</td><td>The pictures you took for video covers</td></tr></tbody></table><p>Your data <strong>will be lost forever</strong> if you do these things:</p><div class="danger custom-block"><p class="custom-block-title">⚠️ Common ways to lose data</p><ul><li>🗑️ <strong>Uninstall the V-Train extension</strong></li><li>🔄 <strong>Reset your browser settings</strong></li><li>💻 <strong>Buy a new computer</strong> or <strong>reinstall your operating system</strong></li><li>🧹 <strong>Clear browser data (Cookies and Cache)</strong></li></ul></div><hr><h2 id="🚀-how-to-backup" tabindex="-1">🚀 How to Backup <a class="header-anchor" href="#🚀-how-to-backup" aria-label="Permalink to &quot;🚀 How to Backup&quot;">​</a></h2><p>You can find the backup buttons at the <strong>top of the Dashboard</strong>.</p><blockquote><p><img src="'+e+'" alt="Backup and Restore Buttons"></p></blockquote><p>Click the <strong>&quot;Export Full Backup&quot;</strong> button. A window will open to let you choose what to save.</p><hr><h2 id="⬆️-export-data-save-a-backup" tabindex="-1">⬆️ Export Data (Save a Backup) <a class="header-anchor" href="#⬆️-export-data-save-a-backup" aria-label="Permalink to &quot;⬆️ Export Data (Save a Backup)&quot;">​</a></h2><h3 id="choose-what-to-backup" tabindex="-1">Choose What to Backup <a class="header-anchor" href="#choose-what-to-backup" aria-label="Permalink to &quot;Choose What to Backup&quot;">​</a></h3><p>You can choose to save one or both of these things:</p><div class="info custom-block"><p class="custom-block-title">📋 Core Data</p><p>This includes: viewing history, rules, bookmarks, ratings, and settings. <strong>This file is very small.</strong> You should back this up every time you train a new website.</p></div><div class="info custom-block"><p class="custom-block-title">🖼️ Image Covers</p><p>This includes: the pictures you took for your video covers. <strong>Warning:</strong> If you have many pictures, this file will be very big. The backup will take more time.</p></div><h3 id="the-backup-process" tabindex="-1">The Backup Process <a class="header-anchor" href="#the-backup-process" aria-label="Permalink to &quot;The Backup Process&quot;">​</a></h3><p>After you click export, a new page will open. It does everything automatically. You just need to wait:</p><blockquote><p><img src="'+o+`" alt="Backup Progress Page"></p></blockquote><ol><li><strong>Initializing</strong>: Getting ready.</li><li><strong>Fetching Core Data</strong>: Reading your history and bookmarks.</li><li><strong>Packaging Images</strong>: Packing your cover pictures.</li><li><strong>Compressing ZIP</strong>: Making the file smaller.</li><li><strong>Download Complete</strong>: The file downloads to your computer. The name is <code>VTrain_Backup_YYYY-MM-DD.zip</code>.</li></ol><div class="tip custom-block"><p class="custom-block-title">💡 Have thousands of pictures?</p><p>V-Train can handle very large backups! It will split your pictures into smaller files so your computer does not crash.</p></div><h3 id="inside-the-backup-file" tabindex="-1">Inside the Backup File <a class="header-anchor" href="#inside-the-backup-file" aria-label="Permalink to &quot;Inside the Backup File&quot;">​</a></h3><p>If you open the ZIP file, you will see files like this:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>VTrain_Backup_2025-01-01.zip</span></span>
<span class="line"><span>├── core_data.json          # Your history, rules, and settings</span></span>
<span class="line"><span>├── images_part_1.json      # The first part of your cover pictures</span></span>
<span class="line"><span>├── images_part_2.json      # The second part of your cover pictures</span></span>
<span class="line"><span>└── ...</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">Keep your backup safe</p><p>You should save this ZIP file in a safe place. Put it on Google Drive, Dropbox, or a USB drive.</p></div><hr><h2 id="⬇️-import-data-restore-a-backup" tabindex="-1">⬇️ Import Data (Restore a Backup) <a class="header-anchor" href="#⬇️-import-data-restore-a-backup" aria-label="Permalink to &quot;⬇️ Import Data (Restore a Backup)&quot;">​</a></h2><h3 id="when-do-you-use-this" tabindex="-1">When do you use this? <a class="header-anchor" href="#when-do-you-use-this" aria-label="Permalink to &quot;When do you use this?&quot;">​</a></h3><ul><li>You bought a new computer.</li><li>You accidentally deleted your browser data.</li><li>You want to copy your rules to another computer.</li></ul><h3 id="how-to-restore" tabindex="-1">How to Restore <a class="header-anchor" href="#how-to-restore" aria-label="Permalink to &quot;How to Restore&quot;">​</a></h3><ol><li>Open the Dashboard.</li><li>Click the <strong>&quot;Import Full Backup&quot;</strong> button at the top.</li><li>A new page will open.</li><li><strong>Drag and drop</strong> your <code>.zip</code> backup file into the page. Or click the button to select the file.</li></ol><blockquote><p><img src="`+a+'" alt="Restore Center Page"></p></blockquote><ol start="5"><li>The system will load your data.</li><li>When it finishes, you can close the page.</li></ol><div class="tip custom-block"><p class="custom-block-title">💡 Refresh your page</p><p>After you restore, you must <strong>refresh</strong> the video website you are looking at.</p></div><h3 id="restore-order" tabindex="-1">Restore Order <a class="header-anchor" href="#restore-order" aria-label="Permalink to &quot;Restore Order&quot;">​</a></h3><p>If you have separate files, restore <code>core_data.json</code> first. Then restore the picture files.</p><hr><h2 id="🔄-using-v-train-on-two-computers" tabindex="-1">🔄 Using V-Train on Two Computers <a class="header-anchor" href="#🔄-using-v-train-on-two-computers" aria-label="Permalink to &quot;🔄 Using V-Train on Two Computers&quot;">​</a></h2><p>V-Train does not sync your data to the cloud automatically. This keeps your data private. If you want to use the same data on two computers:</p><ol><li>Export a backup on <strong>Computer A</strong>.</li><li>Move the ZIP file to <strong>Computer B</strong> (using a USB drive or Google Drive).</li><li>Import the backup on <strong>Computer B</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Easy way to share rules</p><p>Do you want to share a website rule with a friend? You do not need to make a full backup! Go to the Dashboard → Click &quot;Trained Sites&quot; → Click &quot;Share&quot; to copy the serial number. Give this number to your friend.</p></div><hr><h2 id="📋-when-should-i-backup" tabindex="-1">📋 When Should I Backup? <a class="header-anchor" href="#📋-when-should-i-backup" aria-label="Permalink to &quot;📋 When Should I Backup?&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type of User</th><th>How Often to Backup</th></tr></thead><tbody><tr><td>I use it sometimes</td><td>Once a month</td></tr><tr><td>I use it normally</td><td>Every two weeks</td></tr><tr><td>I use it a lot (Many bookmarks)</td><td>Once a week</td></tr><tr><td>I just trained a new website</td><td>Backup right now!</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The most important rule</p><p><strong>Always backup before you update Windows or macOS!</strong> Sometimes system updates delete browser data.</p></div>',48)])])}const y=s(n,[["render",u]]);export{g as __pageData,y as default};
